return [{ json: { chat_id: ctx.chat_id, message: sections.filter(Boolean).join('\n') } }];

const result = $input.first().json.output || {};
const ctx = $('Normalize Research Results').first().json;
const staticData = $getWorkflowStaticData('global');
const contacts = result.contacts || [];
staticData.last_contacts = { contacts, company: ctx.company, role: ctx.role, timestamp: new Date().toISOString() };
if (contacts.length === 0) { const tips = (result.search_tips || []).map(t => '• ' + t).join('
'); return [{ json: { chat_id: ctx.chat_id, message: '\u{1F4E7} *No contacts found for ' + ctx.company + '.*

' + (tips ? '*Search Tips:*
' + tips : 'Try a more specific role.') } }]; }
const lines = contacts.map((c, i) => { const priIcon = c.priority === 'High' ? '\u{1F525}' : c.priority === 'Medium' ? '⭐' : '\u{1F4CC}'; const linkedIn = c.linkedin_url ? ' [LinkedIn](' + c.linkedin_url + ')' : ''; return (i + 1) + '. ' + priIcon + ' *' + c.name + '* — ' + c.role + '
   ' + c.type + ' | ' + (c.location || '?') + ' | Confidence: ' + c.confidence + linkedIn + '
   _' + c.reason + '_'; });
return [{ json: { chat_id: ctx.chat_id, message: '\u{1F4E7} *Contacts at ' + ctx.company + ':*

' + lines.join('

') + '

\u{1F4A1} Reply "draft 1" to generate outreach for contact #1.' } }];

const staticData = $getWorkflowStaticData('global');
const chatId = $('Extract Input').first().json.chat_id;
const ctx = $('Prepare Research').first().json;
const draftNum = ctx.draft_number;
const lastContacts = staticData.last_contacts;
if (!lastContacts || !lastContacts.contacts || lastContacts.contacts.length === 0) return [{ json: { chat_id: chatId, error: 'No contacts to draft for. Run /outreach first.' } }];
const idx = draftNum - 1;
if (idx < 0 || idx >= lastContacts.contacts.length) return [{ json: { chat_id: chatId, error: 'Contact #' + draftNum + ' not found. You have ' + lastContacts.contacts.length + ' contacts.' } }];
const contact = lastContacts.contacts[idx];
const resumeData = staticData.last_apply || {};
return [{ json: { chat_id: chatId, contact, company: lastContacts.company, role: lastContacts.role, candidate_name: (resumeData.personal && resumeData.personal.name) || 'Candidate', candidate_location: (resumeData.personal && resumeData.personal.location) || '', relevant_achievement: resumeData.resume_text ? resumeData.resume_text.substring(0, 500) : '', error: '' } }];

const rawInput = $input.first().json;
const raw = typeof rawInput.text === 'string' ? rawInput.text.trim() : JSON.stringify(rawInput);
const expectedJobs = $('Build Scorer Input').first().json.jobs || [];
const jobById = Object.fromEntries(expectedJobs.map(j => [j.job_id, j]));
let scored = [];
let strategy = 'none';
let parseError = null;
function normalizeScore(jobId, fit) {
  let score = Math.max(0, Math.min(10, Math.round(Number(fit) || 0)));
  if (jobById[jobId] && jobById[jobId].source_tier === 3) score = Math.min(score, 3);
  return score;
}
function validate(items) {
  if (!Array.isArray(items)) return null;
  const valid = items.filter(s => s && typeof s.job_id === 'string' && s.job_id.length > 0).map(s => ({
    job_id: String(s.job_id),
    fit_score: normalizeScore(String(s.job_id), s.fit_score),
    one_liner: String(s.one_liner || 'No summary').substring(0, 100),
    yoe_compatibility: s.yoe_compatibility ?? null,
    detected_location: (s.detected_location != null ? String(s.detected_location).substring(0, 80) : null),
    location_match: (['match','mismatch','unknown'].indexOf(s.location_match) !== -1 ? s.location_match : 'unknown'),
    skills_score: (s.skills_score != null ? Number(s.skills_score) : null),
    experience_score: (s.experience_score != null ? Number(s.experience_score) : null),
    workauth_score: (s.workauth_score != null ? Number(s.workauth_score) : null)
  }));
  return valid.length > 0 ? valid : null;
}
// Strategy 0 — chainLlm's attached output parser puts the validated object under .output
if (!scored.length && rawInput && rawInput.output) { const o = rawInput.output; const v = validate(o.scored) || validate(o); if (v) { scored = v; strategy = 'parsed_output'; } }
if (!scored.length) { try { const parsed = JSON.parse(raw); const result = validate(parsed?.scored); if (result) { scored = result; strategy = 'direct'; } } catch(e) {} }
if (!scored.length) { try { const match = raw.match(/```(?:json)?\s*([\s\S]+?)\s*```/); if (match) { const parsed = JSON.parse(match[1].trim()); const result = validate(parsed?.scored); if (result) { scored = result; strategy = 'markdown_fence'; } } } catch(e) {} }
if (!scored.length) { try { const match = raw.match(/\{[\s\S]*\}/); if (match) { const parsed = JSON.parse(match[0]); const result = validate(parsed?.scored); if (result) { scored = result; strategy = 'regex_object'; } } } catch(e) { parseError = e.message; } }
if (!scored.length) { try { const items = []; const pat = /\{\s*"job_id"\s*:\s*"([^"]+)"\s*,\s*"fit_score"\s*:\s*(\d+)\s*,\s*"one_liner"\s*:\s*"([^"]*)"\s*\}/g; let m; while ((m = pat.exec(raw)) !== null) { items.push({ job_id: m[1], fit_score: normalizeScore(m[1], m[2]), one_liner: m[3].substring(0, 100) }); } if (items.length > 0) { scored = items; strategy = 'item_regex'; } } catch(e) {} }
if (!scored.length) { scored = expectedJobs.map(j => ({ job_id: j.job_id, fit_score: j.source_tier === 3 ? 3 : 5, one_liner: 'Scoring unavailable — showing by source quality' })); strategy = 'neutral_fallback'; parseError = parseError || 'All 4 parsing strategies exhausted'; }
// S3: deterministic /100 composite with explainable sub-scores
const _eq = (() => { try { return $('Parse Expand Query').first().json || {}; } catch(_) { return {}; } })();
const _floor = Number(_eq.salary_min || (_eq.compensation && _eq.compensation.salary_min) || 0) || 0;
const _clamp = n => Math.max(0, Math.min(100, Math.round(Number(n) || 0)));
const _W = { skills: 0.35, experience: 0.20, workauth: 0.15, location: 0.10, company_health: 0.10, compensation: 0.10 };
const _locMap = { match: 100, unknown: 60, mismatch: 20 };
function _comp(job) { if (!_floor) return 60; const lo = job && job.salary_min; if (!lo) return 60; if (lo >= _floor) return 100; return Math.max(20, Math.round((lo / _floor) * 100)); }
scored = scored.map(s => {
  const job = jobById[s.job_id] || {};
  const base = (Number(s.fit_score) || 0) * 10;
  const sub = {
    skills: _clamp(s.skills_score != null ? s.skills_score : base),
    experience: _clamp(s.experience_score != null ? s.experience_score : base),
    workauth: _clamp(s.workauth_score != null ? s.workauth_score : base),
    location: (_locMap[s.location_match] != null ? _locMap[s.location_match] : 60),
    company_health: 60,
    compensation: _comp(job)
  };
  const score100 = Math.round(sub.skills*_W.skills + sub.experience*_W.experience + sub.workauth*_W.workauth + sub.location*_W.location + sub.company_health*_W.company_health + sub.compensation*_W.compensation);
  let _bn = null, _bv = 101; for (const k of Object.keys(sub)) { if (sub[k] < _bv) { _bv = sub[k]; _bn = k; } }
  const bin = score100 >= 70 ? 'Strong' : score100 >= 55 ? 'Good' : score100 >= 40 ? 'Mixed' : 'Poor';
  return Object.assign({}, s, { sub_scores: sub, score100: score100, bin: bin, bottleneck: _bn });
});
return [{ json: { scored, total: scored.length, strategy, parse_error: parseError } }];

// Parse Expand Query v2 — unified intent schema
// Parses LLM output, merges user_prefs, fails loudly on bad output.

const sd = $getWorkflowStaticData('global');
const userPrefs = sd.user_prefs || {};

let llmOutput = '';
try {
  const raw = $input.first().json;
  llmOutput = raw.text || raw.output || raw.response || raw.content || JSON.stringify(raw);
} catch(e) { llmOutput = ''; }

llmOutput = llmOutput.replace(/^```json\s*/i,'').replace(/^```\s*/i,'').replace(/```\s*$/i,'').trim();

let parsed = null;
try { parsed = JSON.parse(llmOutput); } catch(e) {
  const m = llmOutput.match(/\{[\s\S]*\}/);
  if (m) { try { parsed = JSON.parse(m[0]); } catch(e2) {} }
}

if (!parsed) {
  return [{ json: {
    _parse_error: true,
    error_message: "⚠️ I couldn't understand that query. Try something like:\n\n• \"find me AI Engineer jobs in NYC\"\n• \"show remote ML roles, $150k+\"\n• \"search for backend jobs in San Francisco\"",
    raw_output: llmOutput.substring(0, 200)
  }}];
}

if (!parsed.role_families || !Array.isArray(parsed.role_families) || !parsed.role_families.length) {
  return [{ json: {
    _parse_error: true,
    error_message: "⚠️ Couldn't figure out what role you're looking for. Could you be more specific?\n\n• \"find me Data Engineer jobs\"\n• \"show ML Engineer openings, remote\""
  }}];
}

const result = {
  role_families:      parsed.role_families,
  excluded_roles:     parsed.excluded_roles     || userPrefs.excluded_roles     || ["Technical Support","Customer Success","QA Engineer"],
  firecrawl_queries:  parsed.firecrawl_queries   || [],
  youcom_queries:     parsed.youcom_queries       || [],
  serper_queries:     parsed.serper_queries       || [],
  location_canonical: parsed.location_canonical   || userPrefs.location_canonical || null,
  country:            parsed.country              || userPrefs.country             || 'US',
  remote_preference:  parsed.remote_preference    || userPrefs.remote_preference   || 'open',
  freshness:          parsed.freshness            || userPrefs.freshness           || 'qdr:w',
  seniority:          parsed.seniority            || userPrefs.seniority           || 'any',
  max_yoe:            parsed.max_yoe !== undefined ? parsed.max_yoe : (userPrefs.max_yoe || null),
  industry_signals:   parsed.industry_signals     || [],
  visa_signals:       parsed.visa_signals         || [],
  salary_signals:     parsed.salary_signals       || [],
  scoring_priorities: parsed.scoring_priorities   || [],
  verbose:            parsed.verbose              || userPrefs.verbose             || false,
  _schema_version:    2,
  _parsed_at:         new Date().toISOString()
};

// Save for apply flow
// S4: rich structured filters + F-1 OPT ambiguity flag
result.salary_min = (typeof parsed.salary_min === 'number' ? parsed.salary_min : (userPrefs.salary_min || null));
result.equity = !!parsed.equity;
result.sponsorship_required = !!(parsed.sponsorship_required || userPrefs.sponsorship_required);
result.f1_opt_constraint = parsed.f1_opt_constraint || 'none';
result.exclude_recent_layoffs = !!parsed.exclude_recent_layoffs;
result.min_funding_stage = parsed.min_funding_stage || null;
result.culture_constraints = Array.isArray(parsed.culture_constraints) ? parsed.culture_constraints : [];
result.ambiguity_flags = [];
if (result.f1_opt_constraint === 'remote_from_outside_us') {
  result.ambiguity_flags.push('F1_OPT_REMOTE_LOCATION');
  result._f1_note = '🛂 Heads-up: on F-1 OPT, remote work must be performed while physically in the US. I searched anyway, but a US-based role worked from outside the US generally is NOT OPT-eligible — confirm you will be in the US.';
}
sd.last_search_intent = result;

// Build verbose preview message
const filters = [];
if (result.location_canonical) filters.push('📍 ' + result.location_canonical.split(',')[0]);
if (result.salary_signals.length) filters.push('💰 ' + result.salary_signals[0]);
if (result.visa_signals.length) filters.push('🛂 ' + result.visa_signals[0]);
if (result.industry_signals.length) filters.push('🏭 ' + result.industry_signals[0]);
if (result.seniority !== 'any') filters.push('📊 ' + result.seniority);
const remoteIcon = result.remote_preference === 'remote_only' ? ' 🌍 Remote' : '';
result._verbose_message = '🎯 *Searching for:* ' + result.role_families.slice(0,3).join(', ')
  + (result.role_families.length > 3 ? '…' : '') + remoteIcon
  + (filters.length ? '\n' + filters.join(' · ') : '')
  + '\n\n_Reply "edit" to refine, anything else continues._';

return [{ json: result }];

// Build research query. HTTP calls are handled by HTTP Request nodes downstream.
const ctx = $input.first().json;
const company = ctx.company || '';
const researchType = ctx.research_type || 'intel';
const role = ctx.role || 'Software Engineer';
const year = new Date().getFullYear();
const researchQuery = researchType === 'intel'
  ? `Company health analysis for ${company} ${year}: latest news, layoffs, funding rounds, Glassdoor rating, H1B sponsorship, engineering culture, red flags`
  : `Recruiters and hiring managers at ${company} for ${role} positions: LinkedIn profiles, names, titles, contact information`;
return [{ json: { ...ctx, research_query: researchQuery } }];

const jobs = $('Aggregate Jobs').first().json.jobs || [];
const expandCtx = $('Parse Expand Query').first().json;
const maxYoe = expandCtx.max_yoe || null;
const seniorityPref = expandCtx.seniority_pref || 'any';

const seniorityYoe = {
  junior: { min: 0, max: 2 }, 'entry-level': { min: 0, max: 1 }, associate: { min: 0, max: 2 },
  'mid-level': { min: 3, max: 6 }, intermediate: { min: 2, max: 5 },
  senior: { min: 5, max: 99 }, staff: { min: 7, max: 99 },
  principal: { min: 8, max: 99 }, lead: { min: 5, max: 99 },
};

function extractYoe(text) {
  if (!text) return { min: null, max: null };
  const t = text.toLowerCase();
  let m;
  if ((m = t.match(/(\d+)\s*[-–to]+\s*(\d+)\s*(?:years?|yrs?)/i)))
    return { min: parseInt(m[1]), max: parseInt(m[2]) };
  if ((m = t.match(/(\d+)\+\s*(?:years?|yrs?)\s*(?:of\s*)?(?:experience|exp)/i)))
    return { min: parseInt(m[1]), max: 99 };
  if ((m = t.match(/(?:minimum|min\.?|at least)\s*(\d+)\s*(?:years?|yrs?)/i)))
    return { min: parseInt(m[1]), max: 99 };
  if ((m = t.match(/(\d+)\s*(?:years?|yrs?)\s*(?:of\s*)?(?:experience|exp)/i))) {
    const n = parseInt(m[1]);
    return { min: Math.max(0, n - 1), max: n + 2 };
  }
  for (const [label, range] of Object.entries(seniorityYoe)) {
    if (t.includes(label)) return { min: range.min, max: range.max };
  }
  return { min: null, max: null };
}

function calcCompatScore(jobMin, jobMax, userMaxYoe, seniorityPref) {
  if (jobMin === null && jobMax === null) return 1.0;
  if (!userMaxYoe && seniorityPref === 'any') return 1.0;
  let userMin = 0, userMax = userMaxYoe || 99;
  if (seniorityPref === 'junior') { userMin = 0; userMax = Math.min(userMax, 2); }
  else if (seniorityPref === 'mid') { userMin = 2; userMax = Math.min(userMax || 7, 7); }
  else if (seniorityPref === 'senior') { userMin = 5; userMax = 99; }
  const jMin = jobMin ?? 0, jMax = jobMax ?? 99;
  if (userMax >= jMin && userMin <= jMax) return 1.0;
  if (userMin > jMax) return Math.max(0.2, 1.0 - (userMin - jMax) * 0.15);
  if (userMax < jMin) return Math.max(0.1, 1.0 - (jMin - userMax) * 0.2);
  return 1.0;
}

const enrichedJobs = jobs.map(job => {
  const { min, max } = extractYoe(job.description_snippet || job.title || '');
  const compatScore = calcCompatScore(min, max, maxYoe, seniorityPref);
  return { ...job, required_yoe_min: min, required_yoe_max: max, yoe_compat_score: compatScore };
});

const filtered = (maxYoe || seniorityPref !== 'any')
  ? enrichedJobs.filter(j => j.yoe_compat_score >= 0.15)
  : enrichedJobs;

return [{ json: { jobs: filtered, count: filtered.length, filtered_out: enrichedJobs.length - filtered.length } }];

