// Prep Apply Body v2 — pulls pending resume from Supabase lookup, builds sanitized global cf_state row.
const lookup = $input.first().json;
const cb = $('Extract Callback').first().json;
const sd = $getWorkflowStaticData('global');

function cleanString(v) {
  if (v === null || v === undefined) return '';
  return String(v)
    .replace(/\u0000/gi, '')
    .replace(/\x00/gi, '')
    .replace(/\0/g, '')
    .replace(/\p{C}/gu, ch => (ch === '\n' || ch === '\t' ? ch : ' '))
    .replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/g, ' ')
    .trim();
}
function scrub(value, seen = new WeakSet()) {
  if (value === null || value === undefined) return value;
  if (typeof value === 'string') return cleanString(value);
  if (typeof value === 'number' || typeof value === 'boolean') return value;
  if (Array.isArray(value)) return value.map(v => scrub(v, seen));
  if (typeof value === 'object') {
    if (seen.has(value)) return null;
    seen.add(value);
    const out = {};
    for (const [k, v] of Object.entries(value)) out[cleanString(k)] = scrub(v, seen);
    return out;
  }
  return cleanString(value);
}

const pending = Array.isArray(lookup) ? lookup[0] : lookup;
if (!pending || !pending.value || !pending.value.resume_doc) {
  return [{ json: { _error: 'No pending resume found for this preview. Please upload or paste your resume again.', _empty: true, chat_id: cb.chat_id, callback_query_id: cb.callback_query_id } }];
}

const ttlSec = pending.value.ttl_seconds || 600;
const createdAt = new Date(pending.value.created_at || Date.now());
const ageSec = (Date.now() - createdAt.getTime()) / 1000;
if (ageSec > ttlSec) {
  return [{ json: { _error: 'That resume preview expired. Please upload or paste your resume again.', _expired: true, chat_id: cb.chat_id, callback_query_id: cb.callback_query_id } }];
}

const resumeDoc = scrub(pending.value.resume_doc);
